  color: var(--color-content-default);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.01em;
  line-height: 1.1;
}
.cbf-invoice-card__ref {
  min-width: 0;
}
.cbf-invoice-card__ref-name {
  margin: 0;
  font-size: 16px;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default);
  line-height: 1.3;
}
.cbf-invoice-card__ref-link {
  position: relative;
  z-index: 1;
  display: inline-block;
  color: var(--color-background-brand-muted, var(--color-background-brand));
  text-decoration: none;
  cursor: pointer;
}
.cbf-invoice-card__ref-link:hover {
  text-decoration: underline;
}
.cbf-invoice-card__ref-link:focus-visible {
  outline: 2px solid var(--color-background-brand);
  outline-offset: 2px;
  border-radius: var(--radius-050, 2px);
}
.cbf-invoice-card__ref-meta {
  margin: var(--spacing-050) 0 0;
  font-size: 13px;
  color: var(--color-content-default-tertiary);
  font-variant-numeric: tabular-nums;
}
.cbf-vendor-dashboard-invoices__cards .cbf-invoice-group-header {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--spacing-100) var(--spacing-400);
  padding-bottom: var(--spacing-200);
  border-bottom: 1px solid var(--color-border-default);
}
.cbf-vendor-dashboard-invoices__cards .cbf-invoice-group-header:not(:first-child) {
  margin-top: var(--spacing-400);
}
.cbf-vendor-dashboard-invoices__grid .cbf-grid-status {
  display: inline-flex;
  align-items: center;
  height: 100%;
}
.cbf-vendor-dashboard-invoices__grid .cbf-grid-num,
.cbf-vendor-dashboard-invoices__grid .cbf-grid-num .ag-header-cell-label {
  justify-content: flex-end;
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.cbf-vendor-dashboard-invoices__grid .cbf-grid-id {
  font-variant-numeric: tabular-nums;
  color: var(--color-content-default-secondary);
}
.cbf-doc-sheet {
  display: block;
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default-subtle, var(--color-border-default));
  border-radius: var(--radius-100);
  box-shadow: var(--elevation-3, 0 2px 8px -2px rgba(19, 39, 62, 0.12));
  padding: var(--spacing-600);
  color: var(--color-content-default);
}
.cbf-doc__items .cbf-num {
  text-align: right;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.cbf-invoice-pipeline {
  display: flex;
  list-style: none;
  margin: 0;
  padding: 0;
}
.cbf-vendor-dashboard-invoices__header {
  align-items: center;
  gap: var(--spacing-400);
  flex-wrap: wrap;
}
.cbf-vendor-dashboard-invoices__search {
  flex: 1 1 280px;
  max-width: 420px;
  min-width: 220px;
}
.cbf-vendor-dashboard-invoices__controls {
  align-items: center;
  gap: var(--spacing-400);
  flex-wrap: wrap;
}
.cbf-vendor-dashboard-invoices__right {
  align-items: center;
}
.cbf-vendor-dashboard-invoices__group,
.cbf-vendor-dashboard-invoices__view {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-200);
}
.cbf-vendor-dashboard-invoices__group .typography-meta,
.cbf-vendor-dashboard-invoices__view .typography-meta {
  color: var(--color-content-default-tertiary);
  white-space: nowrap;
}
.cbf-vendor-dashboard-invoices__cards {
  --grid-min: max(26rem, calc(50% - var(--gap)));
}
.cbf-vendor-dashboard-invoices__cards[hidden] {
  display: none;
}
.cbf-invoice-card-link {
  position: relative;
  display: block;
  border-radius: var(--radius-200);
}
.cbf-invoice-card-link > .esa-card {
  height: 100%;
  transition:
    border-color 0.12s ease,
    box-shadow 0.12s ease;
}
.cbf-invoice-card-link__open {
  all: unset;
  position: absolute;
  inset: 0;
  z-index: 0;
  cursor: pointer;
  border-radius: inherit;
}
.cbf-invoice-card-link:hover > .esa-card {
  border-color: var(--color-background-brand);
  box-shadow: var(--elevation-3, 0 2px 8px -2px rgba(19, 39, 62, 0.12));
}
.cbf-invoice-card-link:focus-within {
  outline: 2px solid var(--color-background-brand);
  outline-offset: 2px;
  border-radius: var(--radius-200);
}
.cbf-invoice-card-link:has(.cbf-invoice-card__ref-link:focus-visible) {
  outline: none;
}
.cbf-vendor-dashboard-invoices__grid {
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
  overflow: hidden;
  background: var(--color-background-elevation-raised);
}
.cbf-vendor-dashboard-invoices__footer {
  color: var(--color-content-default-tertiary);
}
.cbf-invoice-detail {
  display: grid;
  gap: var(--spacing-500);
}
@media (min-width: 900px) {
  .cbf-invoice-detail {
    grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr);
    grid-template-rows: 1fr;
    align-items: stretch;
    min-height: 100%;
  }
}
@media (min-width: 900px) {
  .cbf-invoice-detail__doc {
    grid-column: 1;
    grid-row: 1;
  }
}
@media (min-width: 900px) {
  .cbf-invoice-detail__meta {
    grid-column: 2;
    grid-row: 1;
  }
}
.cbf-invoice-detail__doc {
  background: var(--color-background-elevation-sunken);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
  padding: var(--spacing-400);
  min-width: 0;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
}
.cbf-doc-sheet {
  flex: 1 0 auto;
}
.cbf-invoice-detail__label {
  font-size: var(--font-size-150);
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-tertiary);
}
.cbf-invoice-detail__hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--spacing-400);
  padding: var(--spacing-450, var(--spacing-400));
  background: var(--color-background-elevation-sunken);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
}
.cbf-invoice-detail__amount-group {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-100);
  min-width: 0;
}
.cbf-invoice-detail__amount {
  color: var(--color-content-default);
  font-variant-numeric: tabular-nums;
}
.cbf-invoice-detail__status {
  flex: none;
}
.cbf-invoice-detail__state {
  font-size: var(--font-size-150);
  color: var(--color-content-default-secondary);
}
.cbf-invoice-detail__vendor {
  margin-top: auto;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-400);
  padding-top: var(--spacing-400);
  border-top: 1px solid var(--color-border-default);
}
.cbf-invoice-detail__vendor[hidden] {
  display: none;
}
.cbf-invoice-detail__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: var(--spacing-300);
}
.cbf-invoice-detail__actions[hidden] {
  display: none;
}
.cbf-invoice-detail__actions [data-detail-discard] {
  margin-right: auto;
}
.cbf-invoice-detail__revision[hidden] {
  display: none;
}
.cbf-invoice-detail__revision-by {
  display: block;
  margin-top: var(--spacing-100);
  font-size: var(--font-size-100, 0.75rem);
  color: var(--color-content-default-tertiary);
}
.cbf-invoice-detail__section-title {
  margin: 0;
  font-size: var(--font-size-200);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.cbf-invoice-detail__attach-head {
  align-items: center;
  gap: var(--spacing-300);
}
.cbf-invoice-attach-list {
  list-style: none;
  margin: var(--spacing-300) 0 0;
  padding: 0;
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-200);
  overflow: hidden;
}
.cbf-invoice-detail__fields {
  margin: 0;
}
.cbf-invoice-detail__row {
  display: grid;
  grid-template-columns: 96px 1fr;
  gap: var(--spacing-400);
  align-items: baseline;
  padding-block: var(--spacing-300);
  border-top: 1px solid var(--color-border-default-subtle, var(--color-border-default));
}
.cbf-invoice-detail__row:first-child {
  border-top: 0;
  padding-top: 0;
}
.cbf-invoice-detail__value {
  margin: 0;
  font-size: var(--font-size-200);
  color: var(--color-content-default-secondary);
}
.cbf-invoice-detail__value--lead {
  font-size: var(--font-size-300);
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default);
}
.cbf-invoice-detail__add-docs {
  margin-top: var(--spacing-300);
}
.cbf-invoice-detail__add-docs[hidden] {
  display: none;
}
.cbf-invoice-detail__add-zone {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-200);
  width: 100%;
  padding: var(--spacing-400);
  border: 1px dashed var(--color-border-default);
  border-radius: var(--radius-200);
  background: var(--color-background-elevation-raised);
  font-size: var(--font-size-150);
  color: var(--color-content-default-secondary);
  cursor: pointer;
  transition:
    border-color 0.12s ease,
    background 0.12s ease;
}
.cbf-invoice-detail__add-zone svg {
  flex: none;
  color: var(--color-background-brand-muted);
}
.cbf-invoice-detail__add-text strong {
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-background-brand-muted);
}
.cbf-invoice-detail__add-zone:hover {
  background: var(--color-background-brand-subtle);
}
.cbf-invoice-detail__add-zone.is-over {
  border-color: var(--color-background-brand);
  border-style: solid;
  background: var(--color-background-brand-subtle);
}
.cbf-invoice-detail__add-zone.is-over {
  pointer-events: none;
}
.cbf-invoice-detail__add-hint {
  margin: var(--spacing-200) 0 0;
  font-size: var(--font-size-100, 0.75rem);
  color: var(--color-content-default-tertiary);
  line-height: 1.5;
}
.cbf-invoice-detail__docs-input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}
.cbf-invoice-detail__position {
  font-size: var(--font-size-150);
  color: var(--color-content-default-tertiary);
  font-variant-numeric: tabular-nums;
}
.cbf-invoice-detail__footer {
  gap: var(--spacing-300);
  flex-wrap: wrap;
}
.esa-alert-box {
  --_alert-bg: var(--color-background-utility-info-subtle, #fbfdff);
  --_alert-border: var(--color-border-utility-info, #acd8fc);
  --_alert-accent: var(--color-content-utility-info, #0d74ce);
  --_alert-icon-color: var(--_alert-accent);
  --_alert-title-color: var(--_alert-accent);
  --_alert-text-color: var(--alert-box-text-color, var(--color-content-default-secondary, #646464));
  display: flex;
  align-items: flex-start;
  gap: var(--spacing-300, 0.75rem);
  padding: var(--spacing-300, 0.75rem) var(--spacing-400, 1rem);
  border: var(--border-width-default, 1px) solid var(--_alert-border);
  border-radius: var(--radius-md, 0.5rem);
  background: var(--_alert-bg);
}
.esa-alert-box--warning {
  --_alert-bg: var(--color-background-utility-warning-subtle, #fefdfb);
  --_alert-border: var(--color-border-utility-warning, #f3d673);
  --_alert-accent: var(--color-content-utility-warning, #ab6400);
}
.esa-alert-box__icon {
  flex-shrink: 0;
  color: var(--_alert-icon-color);
  padding-top: 1px;
}
.esa-alert-box__body {
  flex: 1;
  min-width: 0;
}
.esa-alert-box__title {
  display: block;
  color: var(--_alert-title-color);
  margin-bottom: var(--spacing-050, 0.125rem);
}
.esa-alert-box__message {
  color: var(--_alert-text-color);
}
.cbf-search-field {
  display: flex;
  align-items: center;
  gap: var(--spacing-300);
  width: 100%;
  padding: var(--spacing-300) var(--spacing-400);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-100);
  background: var(--color-background-elevation-raised);
}
.cbf-search-field:focus-within {
  border-color: var(--color-background-brand);
  box-shadow: 0 0 0 3px var(--color-background-brand-subtle);
}
.cbf-search-field .cbf-icon {
  color: var(--color-content-default-tertiary);
  display: inline-flex;
}
.cbf-search-field input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  font-family: var(--typography-font-family-sans);
  font-size: 18px;
  color: var(--color-content-default);
}
.cbf-search-field input::placeholder {
  color: var(--cbf-text-placeholder);
}
.esa-card {
  --_card-bg: var(--card-bg, var(--color-background-elevation-raised, #fcfcfc));
  --_card-border: var(--card-border-color, var(--color-border-default, #cecece));
  --_card-radius: var(--radius-md, 0.5rem);
  --_card-padding: var(--spacing-500, 1.5rem);
  --_card-header-bg: var(--card-header-bg, transparent);
  --_card-header-color: var(--color-content-default, #202020);
  --_card-header-border: var(--color-border-default-subtle, #d9d9d9);
  --_card-meta-label-color: var(--color-content-default-secondary, #646464);
  --_card-meta-label-size: var(--typography-label-sm-font-size, 0.875rem);
  --_card-meta-value-size: var(--typography-label-md-font-size, 0.9375rem);
  display: block;
  background: var(--_card-bg);
  border: var(--border-width-default, 1px) solid var(--_card-border);
  border-radius: var(--_card-radius);
  overflow: hidden;
}
.esa-card__body {
  padding: var(--_card-padding);
}
.esa-pill {
  --_pill-bg: var(--color-background-elevation-sunken, #f0f0f0);
  --_pill-text: var(--color-content-default, #202020);
  --_pill-border: var(--color-border-default-subtle, #d9d9d9);
  --_pill-padding-y: var(--spacing-150, 0.375rem);
  --_pill-padding-x: var(--spacing-200, 0.5rem);
  --_pill-gap: var(--spacing-100, 0.25rem);
  display: inline-flex;
  align-items: center;
  gap: var(--_pill-gap);
  padding-block: var(--_pill-padding-y);
  padding-inline: var(--_pill-padding-x);
  border: var(--border-width-default, 1px) solid var(--_pill-border);
  border-radius: var(--radius-chip, var(--radius-sm, 0.25rem));
  background: var(--_pill-bg);
  color: var(--_pill-text);
  white-space: nowrap;
  box-sizing: border-box;
}
.esa-pill--sm {
  --_pill-padding-y: var(--spacing-100, 0.25rem);
  --_pill-padding-x: var(--spacing-150, 0.375rem);
}
.esa-pill--info {
  --_pill-bg: var(--color-background-utility-info-subtle, var(--color-blue-2));
  --_pill-text: var(--color-content-utility-info, #0d74ce);
  --_pill-border: var(--color-border-utility-info, var(--color-blue-6));
}
.esa-pill--success {
  --_pill-bg: var(--color-background-utility-success-subtle, var(--color-green-2));
  --_pill-text: var(--color-content-utility-success, #218358);
  --_pill-border: var(--color-border-utility-success, var(--color-green-6));
}
.esa-pill--warning {
  --_pill-bg: var(--color-background-utility-warning-subtle, var(--color-yellow-2));
  --_pill-text: var(--color-content-utility-warning, #ab6400);
  --_pill-border: var(--color-border-utility-warning, var(--color-yellow-6));
}
.esa-pill--danger {
  --_pill-bg: var(--color-background-utility-danger-subtle, var(--color-red-2));
  --_pill-text: var(--color-content-utility-danger, #ce2c31);
  --_pill-border: var(--color-border-utility-danger, var(--color-red-6));
}
.esa-pill[data-category] {
  --_pill-bg: var(--category-2, var(--color-background-elevation-sunken, #f0f0f0));
  --_pill-border: var(--category-6, var(--color-border-default-subtle, #d9d9d9));
  --_pill-text: var(--category-11, var(--color-content-default, #202020));
}
.stack {
  --gap: var(--spacing-400, 1rem);
  display: flex;
  flex-direction: column;
  gap: var(--gap);
}
.stack[data-split] > [data-split] {
  margin-block-end: auto;
}
.cluster {
  --gap: var(--spacing-300, 0.75rem);
  --align: center;
  --justify: flex-start;
  display: flex;
  flex-wrap: wrap;
  gap: var(--gap);
  align-items: var(--align);
  justify-content: var(--justify);
}
.repel {
  --gap: var(--spacing-400, 1rem);
  --align: center;
  display: flex;
  flex-wrap: wrap;
  gap: var(--gap);
  align-items: var(--align);
  justify-content: space-between;
}
.grid {
  --gap: var(--spacing-400, 1rem);
  --grid-min: 16rem;
  display: grid;
  gap: var(--gap);
  grid-template-columns: repeat(auto-fit, minmax(min(var(--grid-min), 100%), 1fr));
}
.esa-empty-state {
  --_empty-icon-size: var(--empty-state-icon-size-md, 48px);
  --_empty-gap: var(--spacing-200, 0.5rem);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: var(--spacing-600, 2rem) var(--spacing-400, 1rem);
  gap: var(--_empty-gap);
}
.esa-empty-state--sm {
  --_empty-icon-size: var(--empty-state-icon-size-sm, 32px);
  padding: var(--spacing-400, 1rem) var(--spacing-300, 0.75rem);
}
.esa-empty-state__title {
  margin: 0;
  color: var(--color-content-default, #202020);
}
.esa-empty-state__description {
  margin: 0;
  color: var(--color-content-default-secondary, #646464);
  max-width: 360px;
}
.esa-empty-state__actions {
  margin-top: var(--spacing-200, 0.5rem);
}
.esa-empty-state__actions:empty {
  display: none;
}
